<?php
defined( 'ABSPATH' ) || exit;
final class EduFlow_Class_Service {
	const STATUSES=array('scheduled','completed','cancelled','rescheduled','missed');
	public static function to_utc($date,$time,$timezone){try{$local=new DateTimeImmutable($date.' '.$time,new DateTimeZone($timezone));return $local->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s');}catch(Throwable $e){return new WP_Error('invalid_datetime','Invalid schedule date, time, or timezone.');}}
	public static function conflict($institute_id,$teacher_id,$student_id,$start,$end,$exclude=0){global $wpdb;$table=EduFlow_DB::table('classes');$sql="SELECT canonical_id FROM $table WHERE institute_id=%d AND id<>%d AND class_status IN ('scheduled','rescheduled') AND start_datetime<%s AND end_datetime>%s AND (teacher_id=%d";$params=array($institute_id,$exclude,$end,$start,$teacher_id);if($student_id){$sql.=' OR student_id=%d';$params[]=$student_id;}$sql.=') LIMIT 1';return $wpdb->get_var($wpdb->prepare($sql,...$params));}
	public static function generate_batch($batch_id,$from=null,$days=14,$institute_id=0){global $wpdb;$institute_id=$institute_id?:EduFlow_Settings::institute_db_id();$batch=EduFlow_Batch_Service::get($batch_id,$institute_id);if(!$batch){return new WP_Error('batch_not_found','Batch not found.');}if('active'!==$batch['batch_status']||!$batch['teacher_id']){return array('created'=>0,'skipped'=>0,'conflicts'=>array('Batch is inactive or has no teacher.'));}$teacher=EduFlow_Teacher_Service::get($batch['teacher_id'],$institute_id);if(!$teacher||'active'!==$teacher['teacher_status']){return array('created'=>0,'skipped'=>0,'conflicts'=>array('Assigned teacher is missing or paused.'));}$teacher_days=explode(',',$teacher['available_days']);$from=$from?:current_time('Y-m-d');$start=new DateTimeImmutable($from,new DateTimeZone($batch['timezone']));$last=$start->modify('+'.max(0,absint($days)-1).' days');$batch_start=new DateTimeImmutable($batch['start_date'],new DateTimeZone($batch['timezone']));if($start<$batch_start){$start=$batch_start;}$batch_end=$batch['end_date']?new DateTimeImmutable($batch['end_date'],new DateTimeZone($batch['timezone'])):$last;if($last>$batch_end){$last=$batch_end;}$wanted=explode(',',$batch['days_of_week']);$map=array(1=>'mon',2=>'tue',3=>'wed',4=>'thu',5=>'fri',6=>'sat',7=>'sun');$student_id=null;if(in_array($batch['class_type'],array('1-to-1','demo','trial'),true)){$assign=EduFlow_DB::table('batch_students');$student_id=(int)$wpdb->get_var($wpdb->prepare("SELECT student_id FROM $assign WHERE institute_id=%d AND batch_id=%d AND assignment_status='active' ORDER BY id LIMIT 1",$institute_id,$batch_id))?:null;}$created=0;$skipped=0;$conflicts=array();$table=EduFlow_DB::table('classes');for($date=$start;$date<=$last;$date=$date->modify('+1 day')){if(!in_array($map[(int)$date->format('N')],$wanted,true)){continue;}$day_name=$map[(int)$date->format('N')];$local_date=$date->format('Y-m-d');if($teacher_days&&!in_array($day_name,$teacher_days,true)){$conflicts[]=$local_date.': teacher unavailable';continue;}if($teacher['available_start_time']&&$batch['start_time']<$teacher['available_start_time']||$teacher['available_end_time']&&$batch['end_time']>$teacher['available_end_time']){$conflicts[]=$local_date.': outside teacher availability';continue;}$daily=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $table WHERE institute_id=%d AND teacher_id=%d AND class_date=%s AND class_status IN ('scheduled','rescheduled','completed')",$institute_id,$batch['teacher_id'],$local_date));if($daily>=(int)$teacher['maximum_daily_classes']){$conflicts[]=$local_date.': teacher daily limit reached';continue;}$begin=self::to_utc($local_date,$batch['start_time'],$batch['timezone']);$finish=self::to_utc($local_date,$batch['end_time'],$batch['timezone']);if(is_wp_error($begin)||is_wp_error($finish)||$begin>=$finish){$conflicts[]=$local_date.': invalid time';continue;}$key=$institute_id.':'.$batch_id.':'.$local_date.':'.$batch['start_time'].':'.($student_id?:'batch');if($wpdb->get_var($wpdb->prepare("SELECT id FROM $table WHERE schedule_key=%s",$key))){$skipped++;continue;}$conflict=self::conflict($institute_id,$batch['teacher_id'],$student_id,$begin,$finish);if($conflict){$conflicts[]=$local_date.': conflicts with '.$conflict;continue;}$canonical=EduFlow_ID_Service::generate('class',$institute_id);if(is_wp_error($canonical)){$conflicts[]=$canonical->get_error_message();continue;}$now=current_time('mysql',true);$data=array('canonical_id'=>$canonical,'schedule_key'=>$key,'institute_id'=>$institute_id,'batch_id'=>$batch_id,'student_id'=>$student_id,'teacher_id'=>$batch['teacher_id'],'class_type'=>$batch['class_type'],'class_date'=>$local_date,'start_datetime'=>$begin,'end_datetime'=>$finish,'timezone'=>$batch['timezone'],'meet_url'=>null,'external_event_id'=>null,'class_status'=>'scheduled','status'=>'active','created_at'=>$now,'updated_at'=>$now);if(false!==$wpdb->insert($table,$data)){$created++;$lecture_id=(int)$wpdb->insert_id;EduFlow_Audit_Service::log('lecture_generated','class',$canonical,null,$data,$institute_id);EduFlow_Notification_Service::notify_class($lecture_id,'class_scheduled','Class scheduled','A class has been scheduled.',$now,$institute_id);EduFlow_Google_Service::queue($lecture_id,'upsert',$institute_id);}else{$skipped++;}}return array('created'=>$created,'skipped'=>$skipped,'conflicts'=>$conflicts);}
	public static function generate_rolling($institute_id=0){global $wpdb;$institute_id=$institute_id?:EduFlow_Settings::institute_db_id();$table=EduFlow_DB::table('batches');$ids=$wpdb->get_col($wpdb->prepare("SELECT id FROM $table WHERE institute_id=%d AND batch_status='active'",$institute_id));$results=array();foreach($ids as $id){$results[$id]=self::generate_batch($id,current_time('Y-m-d'),14,$institute_id);}return $results;}
	public static function get($id,$institute_id=0,$lock=false){global $wpdb;$table=EduFlow_DB::table('classes');$institute_id=$institute_id?:EduFlow_Settings::institute_db_id();return $wpdb->get_row($wpdb->prepare("SELECT * FROM $table WHERE id=%d AND institute_id=%d".($lock?' FOR UPDATE':''),$id,$institute_id),ARRAY_A);}
	public static function reschedule($id,$input,$institute_id=0){global $wpdb;$institute_id=$institute_id?:EduFlow_Settings::institute_db_id();$wpdb->query('START TRANSACTION');$old=self::get($id,$institute_id,true);if(!$old){$wpdb->query('ROLLBACK');return new WP_Error('not_found','Lecture not found.');}if('completed'===$old['class_status']){$wpdb->query('ROLLBACK');return new WP_Error('completed_locked','Completed lectures cannot be rescheduled.');}$batch=EduFlow_Batch_Service::get($old['batch_id'],$institute_id);$date=sanitize_text_field($input['class_date']??$old['class_date']);if($date<$batch['start_date']||($batch['end_date']&&$date>$batch['end_date'])){$wpdb->query('ROLLBACK');return new WP_Error('outside_batch_dates','Lecture must remain within batch dates.');}$teacher=absint($input['teacher_id']??$old['teacher_id']);if(!EduFlow_Teacher_Service::get($teacher,$institute_id)){$wpdb->query('ROLLBACK');return new WP_Error('invalid_teacher','Teacher not found.');}$start=self::to_utc($date,sanitize_text_field($input['start_time']??$batch['start_time']),$old['timezone']);$end=self::to_utc($date,sanitize_text_field($input['end_time']??$batch['end_time']),$old['timezone']);if(is_wp_error($start)||is_wp_error($end)||$start>=$end){$wpdb->query('ROLLBACK');return new WP_Error('invalid_time','End time must follow start time.');}$conflict=self::conflict($institute_id,$teacher,$old['student_id'],$start,$end,$id);if($conflict){$wpdb->query('ROLLBACK');return new WP_Error('schedule_conflict','Conflicts with '.$conflict);}$data=array('teacher_id'=>$teacher,'class_date'=>$date,'start_datetime'=>$start,'end_datetime'=>$end,'class_status'=>'rescheduled','original_values'=>$old['original_values']?:wp_json_encode($old),'updated_at'=>current_time('mysql',true));$wpdb->update(EduFlow_DB::table('classes'),$data,array('id'=>$id,'institute_id'=>$institute_id));$wpdb->query('COMMIT');EduFlow_Audit_Service::log('lecture_rescheduled','class',$old['canonical_id'],$old,$data,$institute_id);EduFlow_Notification_Service::notify_class($id,'class_rescheduled','Class rescheduled','An assigned class was rescheduled.',$data['updated_at'],$institute_id);EduFlow_Google_Service::queue($id,'upsert',$institute_id);return true;}
	public static function cancel($id,$institute_id=0){global $wpdb;$institute_id=$institute_id?:EduFlow_Settings::institute_db_id();$old=self::get($id,$institute_id);if(!$old){return new WP_Error('not_found','Lecture not found.');}if('completed'===$old['class_status']){return new WP_Error('completed_locked','Completed lectures cannot be cancelled.');}if('cancelled'===$old['class_status']){return true;}$wpdb->update(EduFlow_DB::table('classes'),array('class_status'=>'cancelled','original_values'=>$old['original_values']?:wp_json_encode($old),'updated_at'=>current_time('mysql',true)),array('id'=>$id,'institute_id'=>$institute_id));EduFlow_Audit_Service::log('lecture_cancelled','class',$old['canonical_id'],$old,array('class_status'=>'cancelled'),$institute_id);EduFlow_Notification_Service::notify_class($id,'class_cancelled','Class cancelled','An assigned class was cancelled.','cancelled',$institute_id);EduFlow_Google_Service::queue($id,'cancel',$institute_id);return true;}
}
